def task_func(task_prompt: str) -> float:
    import re
    from nltk.tokenize import sent_tokenize
    m = re.search(r"```(?:python)?\n(.*?)```", task_prompt, re.DOTALL)
    t = task_prompt[:m.start()] if m else task_prompt
    sents = [s for s in sent_tokenize(t.strip()) if s.strip()]
    if not sents:
        return 0.0
    verbos = r"^(Extract|Generate|Compute|Calculate|Create|Return|Convert|Parse|Read|Write|Check|Validate|Find|Count|Remove|Add|Merge|Split|Filter|Sort|Build|Plot|Load|Save)\b"
    return float(sum(1 for s in sents if re.match(verbos, s.strip())) / len(sents))
